function drawRoyalBoard(room){const c=$("royal-board"),x=c.getContext("2d"),cell=c.width/15;x.fillStyle="#f7f5ec";x.fillRect(0,0,c.width,c.height);const blocks={blue:[0,0],green:[9,0],gold:[0,9],red:[9,9]};for(const [color,[gx,gy]] of Object.entries(blocks)){x.fillStyle=ROYAL_COLORS[color];x.fillRect(gx*cell,gy*cell,6*cell,6*cell);x.fillStyle="#fff";x.fillRect((gx+1)*cell,(gy+1)*cell,4*cell,4*cell)}function square(p,fill="#fff"){x.fillStyle=fill;x.fillRect(p[0]*cell,p[1]*cell,cell,cell);x.strokeStyle="#26364b";x.lineWidth=1.5;x.strokeRect(p[0]*cell,p[1]*cell,cell,cell)}ROYAL_PATH.forEach((p,i)=>square(p,[0,13,26,39].includes(i)?Object.values(ROYAL_COLORS)[[0,13,26,39].indexOf(i)]:"#fff"));for(const [color,lane] of Object.entries(ROYAL_LANES))lane.forEach(p=>square(p,ROYAL_COLORS[color]));x.beginPath();x.moveTo(6*cell,6*cell);x.lineTo(9*cell,6*cell);x.lineTo(7.5*cell,7.5*cell);x.closePath();x.fillStyle=ROYAL_COLORS.green;x.fill();x.beginPath();x.moveTo(9*cell,6*cell);x.lineTo(9*cell,9*cell);x.lineTo(7.5*cell,7.5*cell);x.closePath();x.fillStyle=ROYAL_COLORS.red;x.fill();x.beginPath();x.moveTo(9*cell,9*cell);x.lineTo(6*cell,9*cell);x.lineTo(7.5*cell,7.5*cell);x.closePath();x.fillStyle=ROYAL_COLORS.gold;x.fill();x.beginPath();x.moveTo(6*cell,9*cell);x.lineTo(6*cell,6*cell);x.lineTo(7.5*cell,7.5*cell);x.closePath();x.fillStyle=ROYAL_COLORS.blue;x.fill();royalHits=[];const occupied={};for(const p of room.players){const tokens=room.royal.tokens[p.id]||[];tokens.forEach((progress,i)=>{let pos;if(progress<0)pos=ROYAL_BASES[p.royalColor][i];else if(progress<52){const q=ROYAL_PATH[(ROYAL_OFFSETS[p.royalColor]+progress)%52];pos=[q[0]+.5,q[1]+.5]}else if(progress<58){const q=ROYAL_LANES[p.royalColor][progress-52];pos=[q[0]+.5,q[1]+.5]}else pos=[7.5+(i-1.5)*.18,7.5];const key=`${pos[0].toFixed(1)},${pos[1].toFixed(1)}`,n=occupied[key]||0;occupied[key]=n+1;const angle=n*1.7;pos=[pos[0]+Math.cos(angle)*n*.13,pos[1]+Math.sin(angle)*n*.13];const cx=pos[0]*cell,cy=pos[1]*cell,legal=p.id===session.playerId&&room.royal.legal.includes(i);if(legal){x.beginPath();x.arc(cx,cy,cell*.39,0,Math.PI*2);x.fillStyle="#fff59a";x.fill()}x.beginPath();x.arc(cx,cy,cell*.36,0,Math.PI*2);x.fillStyle=ROYAL_COLORS[p.royalColor];x.fill();x.strokeStyle="#fff";x.lineWidth=3;x.stroke();x.fillStyle="#071329";x.font=`bold ${cell*.25}px Arial`;x.textAlign="center";x.textBaseline="middle";x.fillText(String(i+1),cx,cy);if(legal)royalHits.push({tokenIndex:i,x:cx,y:cy,r:cell*.56})})}}
