$("audio-toggle").onclick=()=>{unlockAudio();renderAudioControls();$("audio-modal").classList.remove("hidden")};$("audio-close").onclick=()=>$("audio-modal").classList.add("hidden");$("audio-modal").onclick=event=>{if(event.target===$("audio-modal"))$("audio-modal").classList.add("hidden")};
document.querySelectorAll("[data-audio-setting]").forEach(input=>input.oninput=()=>{audioSettings[input.dataset.audioSetting]=Number(input.value);saveAudioSettings();renderAudioControls()});
document.querySelectorAll("[data-board]").forEach(button=>button.onclick=()=>{boardGame=button.dataset.board;document.querySelectorAll("[data-board]").forEach(b=>b.classList.toggle("selected",b===button));renderLeaderboard(state);if(boardGame==="global")loadGlobalLeaderboard()});
$("leave").onclick=async()=>{const leaving=session;$("leave").disabled=true;try{await fetch("/api/leave",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(leaving),keepalive:true})}finally{source?.close();localStorage.removeItem("tmgr-session");session=null;location.reload()}};
$("code").oninput=e=>e.target.value=e.target.value.toUpperCase().replace(/[^A-Z0-9]/g,"");
const canvas=$("draw-canvas"),ctx=canvas.getContext("2d");let drawing=false,activeDrawPointer=null,activeStrokeId="",batch=[],previous=null,previous2=null,lastFlush=0;
const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]};
function localCurve(a,b,c){ctx.strokeStyle=$("draw-colour").value;ctx.lineWidth=Number($("draw-size").value);ctx.lineCap="round";ctx.lineJoin="round";ctx.beginPath();if(!a){ctx.moveTo(b[0]*canvas.width,b[1]*canvas.height);ctx.lineTo(c[0]*canvas.width,c[1]*canvas.height)}else{ctx.moveTo((a[0]+b[0])*.5*canvas.width,(a[1]+b[1])*.5*canvas.height);ctx.quadraticCurveTo(b[0]*canvas.width,b[1]*canvas.height,(b[0]+c[0])*.5*canvas.width,(b[1]+c[1])*.5*canvas.height)}ctx.stroke()}
function finishLocalCurve(){if(!previous||!previous2)return;ctx.beginPath();ctx.moveTo((previous2[0]+previous[0])*.5*canvas.width,(previous2[1]+previous[1])*.5*canvas.height);ctx.lineTo(previous[0]*canvas.width,previous[1]*canvas.height);ctx.stroke()}
function flushStroke(){if(batch.length<2)return;const points=batch;batch=[batch.at(-1)];lastFlush=performance.now();post("draw-stroke",{color:$("draw-colour").value,size:Number($("draw-size").value),points,strokeId:activeStrokeId}).catch(e=>error("room-error",e.message));}
canvas.addEventListener("pointerdown",e=>{if(!state?.draw?.isDrawer||state.phase!=="draw"||drawing||e.pointerType==="touch"&&(!e.isPrimary||Math.max(e.width,e.height)>48))return;drawing=true;activeDrawPointer=e.pointerId;activeStrokeId=globalThis.crypto?.randomUUID?.()||`${session.playerId}-${Date.now()}`;canvas.setPointerCapture(e.pointerId);previous=point(e);previous2=null;batch=[previous];e.preventDefault()});
canvas.addEventListener("pointermove",e=>{if(!drawing||e.pointerId!==activeDrawPointer)return;for(const sample of e.getCoalescedEvents?.()||[e]){const p=point(sample);localCurve(previous2,previous,p);previous2=previous;previous=p;batch.push(p)}if(performance.now()-lastFlush>40)flushStroke();e.preventDefault()});
function finishDrawingPointer(e){if(!drawing||e&&e.pointerId!==activeDrawPointer)return;drawing=false;finishLocalCurve();flushStroke();activeDrawPointer=null;activeStrokeId="";previous=previous2=null;e?.preventDefault()}
canvas.addEventListener("pointerup",finishDrawingPointer);canvas.addEventListener("pointercancel",finishDrawingPointer);canvas.addEventListener("lostpointercapture",finishDrawingPointer);
refreshAccount();if(session?.code)connect();addEventListener("pointerdown",unlockAudio,{once:true});addEventListener("keydown",unlockAudio,{once:true});
